    id integer NOT NULL,
    folio character varying(25) NOT NULL,
    fecha_venta timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    cliente_id integer,
    cliente_nombre character varying(500) DEFAULT 'Público General'::character varying,
    vendedor_usuario_id integer,
    vendedor_nombre character varying(255) NOT NULL,
    sucursal_id integer,
    subtotal numeric(12,2) NOT NULL,
    descuento_pct numeric(5,2) DEFAULT 0,
    descuento_monto numeric(12,2) DEFAULT 0,
    total numeric(12,2) NOT NULL,
    monto_recibido numeric(12,2),
    cambio numeric(12,2) DEFAULT 0,
    metodo_pago_codigo character varying(30),
    metodo_pago_descripcion character varying(100),
    descuento_config_id integer,
    descuento_autorizado_por character varying(255),
    estatus character varying(20) DEFAULT 'completada'::character varying,
    motivo_cancelacion text,
    notas text,
    ticket_generado boolean DEFAULT false,
    requiere_factura boolean DEFAULT false,
    factura_id integer,
    iva_monto numeric(12,2) DEFAULT 0,
    isr_monto numeric(12,2) DEFAULT 0,
    fecha_modificacion timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    origen_venta character varying(15) DEFAULT 'directa'::character varying NOT NULL,
    tipo_persona_factura character varying(2) DEFAULT 'pm'::character varying NOT NULL,
    pedido_anticipo_monto numeric(12,2) DEFAULT 0,
    pedido_anticipo_metodo character varying(100),
    es_trabajo_equipo boolean DEFAULT false NOT NULL,
    CONSTRAINT chk_pos_ventas_descuento_monto CHECK ((descuento_monto >= (0)::numeric)),
    CONSTRAINT chk_pos_ventas_descuento_pct CHECK (((descuento_pct >= (0)::numeric) AND (descuento_pct <= (100)::numeric))),
    CONSTRAINT chk_pos_ventas_estatus CHECK (((estatus)::text = ANY (ARRAY[('completada'::character varying)::text, ('cancelada'::character varying)::text, ('devuelta'::character varying)::text]))),
    CONSTRAINT chk_pos_ventas_origen CHECK (((origen_venta)::text = ANY (ARRAY[('directa'::character varying)::text, ('pedido'::character varying)::text, ('cotizacion'::character varying)::text]))),
    CONSTRAINT chk_pos_ventas_subtotal CHECK ((subtotal >= (0)::numeric)),
    CONSTRAINT chk_pos_ventas_total CHECK ((total >= (0)::numeric))
);


--
-- Name: TABLE pos_ventas; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.pos_ventas IS 'Registro de ventas del Punto de Venta - cabecera de cada transacción';


